<?php $candidateJson=Json::htmlEncode($candidates);$this->registerJs(<<<JS
(function(){var people={$candidateJson},body=document.getElementById('candidate-body'),item=document.getElementById('bulk-item'),type=document.getElementById('bulk-type'),search=document.getElementById('bulk-search');function money(v){return Number(v||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});}function sum(){var c=Array.from(body.querySelectorAll('.pcheck:checked')),t=c.reduce(function(s,x){return s+Number(body.querySelector('.pamount[data-id="'+x.value+'"]').value||0);},0);document.getElementById('selected-count').textContent='เลือกแล้ว '+c.length+' คน';document.getElementById('selected-total').textContent='ยอดรวม '+money(t)+' บาท';document.getElementById('bulk-submit').disabled=!c.length;}function filter(){var typ=type.value,k=search.value.trim().toLocaleLowerCase('th-TH'),v=[];body.querySelectorAll('tr').forEach(function(r){var show=(!typ||r.dataset.type===typ)&&(!k||r.dataset.search.indexOf(k)!==-1);r.hidden=!show;if(show)v.push(r);});var all=document.getElementById('select-visible');all.checked=v.length>0&&v.every(function(r){return r.querySelector('.pcheck').checked;});all.indeterminate=!all.checked&&v.some(function(r){return r.querySelector('.pcheck').checked;});}function render(){body.textContent='';var salary=item.options[item.selectedIndex]&&item.options[item.selectedIndex].dataset.code==='SALARY';people.forEach(function(p){var r=document.createElement('tr');r.dataset.type=String(p.type_id||'');r.dataset.search=(p.name+' '+p.cid+' '+p.department).toLocaleLowerCase('th-TH');var a=document.createElement('td'),ch=document.createElement('input');ch.type='checkbox';ch.className='form-check-input pcheck';ch.name='employee_ids[]';ch.value=p.id;a.appendChild(ch);var b=document.createElement('td'),n=document.createElement('strong');n.textContent=p.name;var cid=document.createElement('div');cid.className='small text-body-secondary font-monospace';cid.textContent=p.cid||'ไม่พบเลขประชาชน';b.append(n,cid);var d=document.createElement('td');d.textContent=p.type_name;var dep=document.createElement('div');dep.className='small text-body-secondary';dep.textContent=p.department;d.appendChild(dep);var e=document.createElement('td'),amt=document.createElement('input');amt.className='form-control text-end pamount';amt.type='number';amt.min='.01';amt.step='.01';amt.name='amounts['+p.id+']';amt.dataset.id=p.id;amt.value=salary&&Number(p.salary)>0?Number(p.salary).toFixed(2):'';e.appendChild(amt);ch.addEventListener('change',function(){filter();sum();});amt.addEventListener('input',sum);r.append(a,b,d,e);body.appendChild(r);});filter();sum();}document.querySelectorAll('.open-bulk').forEach(function(b){b.addEventListener('click',function(){item.value=b.dataset.itemId;render();});});item.addEventListener('change',render);type.addEventListener('change',filter);search.addEventListener('input',filter);document.getElementById('select-visible').addEventListener('change',function(){var c=this.checked;body.querySelectorAll('tr:not([hidden]) .pcheck').forEach(function(x){x.checked=c;});sum();});document.getElementById('apply-common').addEventListener('click',function(){var v=Number(document.getElementById('common-amount').value);if(v<=0)return;body.querySelectorAll('.pcheck:checked').forEach(function(c){body.querySelector('.pamount[data-id="'+c.value+'"]').value=v.toFixed(2);});sum();});document.querySelectorAll('.edit-item').forEach(function(b){b.addEventListener('click',function(){var d=JSON.parse(b.dataset.item),m={id:'edit-id',employee_id:'edit-employee',item_type_id:'edit-item',amount:'edit-amount',effective_from:'edit-from',effective_to:'edit-to',reference_no:'edit-reference',reason:'edit-reason'};Object.keys(m).forEach(function(k){document.getElementById(m[k]).value=d[k]||'';});});});var list=document.getElementById('sortable-list'),drag;if(list){list.querySelectorAll('tr[draggable]').forEach(function(r){r.addEventListener('dragstart',function(){drag=r;r.classList.add('opacity-50');});r.addEventListener('dragend',function(){r.classList.remove('opacity-50');drag=null;});r.addEventListener('dragover',function(e){e.preventDefault();if(!drag||drag===r)return;var box=r.getBoundingClientRect();list.insertBefore(drag,e.clientY<box.top+box.height/2?r:r.nextSibling);Array.from(list.querySelectorAll('tr[data-row-id]')).forEach(function(x,i){x.querySelector('.document-order').textContent=i+1;});document.getElementById('save-order').disabled=false;});});document.getElementById('reorder-form')?.addEventListener('submit',function(){var box=document.getElementById('ordered-inputs');box.textContent='';list.querySelectorAll('tr[data-row-id]').forEach(function(r){var x=document.createElement('input');x.type='hidden';x.name='ordered_ids[]';x.value=r.dataset.rowId;box.appendChild(x);});});}})();
JS);?>
